    const ctxTokens = parseInt(String(localContextLength), 10);
    if (!Number.isFinite(ctxTokens) || ctxTokens < 2048) return baseLimit;
    return Math.max(8e3, Math.min(9e4, Math.floor((ctxTokens - 3e3) * 3)));
