    "-vl(?:$|[-_:\\s])",
    "multimodal",
    "llava",
    "bakllava",
    "moondream",
    "minicpm-?v",
    "internvl",
    "molmo",
    "smolvlm",
    "pixtral",
    "paligemma",
    "phi-?3\\.5-?vision",
    "phi-?4-?multimodal",
    "kimi-?vl",
    "glm-?4v",
    // Natively multimodal families without "vision" in their model ID
    "qwen3\\.[589]",
    "qwen3-?vl",
    "qwen2\\.5-?vl",
    "qwen2-?vl",
    "qwen-?vl",
    "gemma-?3(?!n)",
    "gemma3",
    "llama-?4",
    "llama4",
    "gpt-?4o",
    "gpt-?4\\.1",
    "gpt-?4\\.5",
    "gpt-?5",
    "(?:^|[/:_-])o[134](?:$|[-_:\\s])",
    "claude-?3",
    "claude-?(?:sonnet|opus|haiku)-?4",
    "gemini-?1\\.5",
    "gemini-?2",
    "gemini-?3",
    "mistral-?small-?3",
    "magistral",
    "grok-?3",
